import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第四十二章 内心没有可以砍伐的树木","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/42第四十二章 内心没有可以砍伐的树木.md","filePath":"meditation/巴利文大藏经/42第四十二章 内心没有可以砍伐的树木.md"}'),o={name:"meditation/巴利文大藏经/42第四十二章 内心没有可以砍伐的树木.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第四十二章-内心没有可以砍伐的树木" tabindex="-1">第四十二章 内心没有可以砍伐的树木 <a class="header-anchor" href="#第四十二章-内心没有可以砍伐的树木" aria-label="Permalink to &quot;第四十二章 内心没有可以砍伐的树木&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应17经/监工经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，佛陀住在骄萨罗国的某处森林中，那时，有个婆罗门正在监督工人砍伐树木，他看见佛陀正在一颗大树下静坐，于是他心里就想：「我在这片森林里监督工人砍伐树木，我以监督工人砍伐树木为乐，而这个静坐的出家人，他以什么为乐呢？」</p><p>想完，这个婆罗门就走到佛陀的身边，他对佛陀说：“出家人，你来这片森林想要干什么呢？难道你也有工作吗？你独自一人在这里静坐以什么为乐呢？”</p><p>这时，婆罗门说偈言：</p><p>「比丘汝于此，沙罗树森林。</p><p>以为何事耶，唯独于森林。</p><p>瞿昙有何乐。」</p><p>佛陀说：“如来独自在这片森林里，没有什么应该要做的事情，就如同森林里面所有树木花草的根已经被断尽，如来心中的树木花草已经全部枯萎消失，如来心中没有树木花草、森林的存在，也就无需再挂念和执着它们的存在，当然也不会再被森林中烦恼和痛苦的荆棘尖刺所刺伤。如来没有任何的念想在内心中生起，也没有任何的欲望在内心中生起，内心没有任何喜怒哀乐等等的念想生起。既然如来内心没有生起各种念想，就不会被一切的烦恼和痛苦所束缚和捆绑，就从一切的烦恼和痛苦中解脱了出来。”</p><p>这时，佛陀说偈言：</p><p>「我独在森林，以行所应行。</p><p>一切森或丛，皆是我所断。</p><p>然我于森林，无有烦恼系。</p><p>亦无刺所刺，无乐亦无悲。」</p><p>佛陀说法后，婆罗门立刻跪在地上顶礼佛陀，他对佛陀说：“大德，您说的太好了，快乐也是烦恼呀，我现在在这里监督工人们砍伐树木，内心非常的开心快乐，如果这里的树木花草全部都枯萎消失了，我们没有树木可以砍伐的时候，我们就会痛苦不堪的，因为我们就无法以砍伐树木为生了，我们无法再出售木材，无法再获得钱财收入，我们的生活就会陷入贫困之中，所以我的这个监督工人砍伐树木的快乐是暂时的，无法永远让这样的快乐一直持续下去，当这片森林不存在了，当这些树木全部都枯萎消失或者被我们砍伐光了，我们的生活贫困潦倒的时候，我们就会陷入到痛苦之中，也就是说我之前监督工人砍伐树木有多大的快乐，那么当这片森林不存在了，我无法再继续监督工人砍伐树木的时候，我就会产生多大的痛苦。</p><p>所谓的快乐最终也会变成痛苦，而大德，您没有什么应该要做的事情。既然您没有做什么事情，也不会为什么事情而开心，不会为什么事情而痛苦，没有快乐痛苦等等感受的产生，就不会有烦恼和痛苦的产生，就从这些世间的事物事情中解脱了出来。</p><p>大德，请您让我皈依您，我愿意做您的在家修行弟子，我愿意受持您的戒律，我愿意按您的正法去修行。”</p><p>佛陀接受了这个婆罗门的皈依。</p>',19)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
